<script setup lang="ts">
import {ref,computed,watch,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useQuasar} from 'quasar'
import {Bell,CheckCircle2,TriangleAlert,X,MessageSquare,Check,Search,RefreshCw} from 'lucide-vue-next'
import {api,allPages} from '../services/api'
import {useMonitor} from '../stores/monitor'
import {date,relative} from '../services/format'
import type {Incident} from '../types'
import StatusBadge from '../components/StatusBadge.vue'
const store=useMonitor(),route=useRoute(),router=useRouter(),$q=useQuasar()
const incidents=ref<Incident[]>([]),selected=ref<Incident|null>(null),filter=ref('active'),search=ref(''),comment=ref(''),loading=ref(false),saving=ref(false),error=ref('')
const filtered=computed(()=>incidents.value.filter(i=>`${i.title} ${i.server_name}`.toLowerCase().includes(search.value.toLowerCase())))
const canAct=computed(()=>!!selected.value&&store.data?.servers.some(s=>s.id===selected.value?.server&&['admin','operator'].includes(s.role)))
async function selectFromRoute(){if(!route.query.incident){selected.value=null;return}try{selected.value=await api(`/incidents/${route.query.incident}`)}catch(e){error.value=(e as Error).message}}
async function load(){loading.value=true;error.value='';try{incidents.value=await allPages(`/incidents?state=${filter.value}`);await selectFromRoute()}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
watch(filter,load);watch(()=>route.query.incident,selectFromRoute);watch(()=>store.data?.updated_at,load);onMounted(load)
function close(){selected.value=null;comment.value='';void router.replace('/alerts')}
async function acknowledge(){if(!selected.value)return;saving.value=true;try{selected.value=await api(`/incidents/${selected.value.id}/acknowledge`,{method:'POST',body:'{}'});await load();await store.refresh();$q.notify({message:'Acknowledged. Reminders are paused; monitoring continues.',color:'positive'})}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function addComment(){if(!selected.value||!comment.value.trim())return;saving.value=true;try{await api(`/incidents/${selected.value.id}/comments`,{method:'POST',body:JSON.stringify({message:comment.value})});comment.value='';await selectFromRoute()}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
</script>
<template><div class="page-header"><div><h1>Alerts</h1><p class="subtitle">Every incident, from detection to recovery.</p></div><q-btn outline no-caps :loading="loading" @click="load"><RefreshCw :size="16"/>Refresh</q-btn></div><div class="list-toolbar"><div class="filter-tabs"><button v-for="f in [{value:'active',label:'Active'},{value:'acknowledged',label:'Acknowledged'},{value:'resolved',label:'Resolved'}]" :key="f.value" :class="{selected:filter===f.value}" @click="filter=f.value">{{f.label}}</button></div><label class="search-box"><Search :size="17"/><input v-model="search" placeholder="Search incidents…" aria-label="Search incidents"/></label></div><div v-if="error" class="error-box" role="alert">{{error}}</div><section class="panel"><button v-for="i in filtered" :key="i.id" class="incident-list-row" @click="router.push(`/alerts?incident=${i.id}`)"><div class="incident-symbol" :class="i.state==='resolved'?'good':i.severity==='warning'?'warn':'bad'"><CheckCircle2 v-if="i.state==='resolved'" :size="23"/><TriangleAlert v-else :size="23"/></div><div class="incident-list-copy"><strong>{{i.title}}</strong><small>{{i.server_name}}<template v-if="i.application_name"> · {{i.application_name}}</template> · {{i.rule.replace(/_/g,' ')}}</small></div><StatusBadge :status="i.state"/><small class="muted">{{relative(i.opened_at)}}</small></button><div v-if="!filtered.length&&!loading" class="empty"><CheckCircle2 :size="36"/><b>{{filter==='active'?'All clear':'No incidents found'}}</b><span>{{filter==='active'?'There are no active incidents.':'Try another filter or search.'}}</span></div><div v-if="loading&&!incidents.length" class="empty"><q-spinner color="primary"/>Loading incidents…</div></section>
<q-dialog :model-value="!!selected" position="right" full-height @update:model-value="v=>{if(!v)close()}"><q-card v-if="selected" class="detail-panel"><header class="detail-header"><div class="detail-icon bad"><Bell :size="23"/></div><div><h2>Incident #{{selected.id}}</h2><p>{{selected.server_name}}</p></div><q-btn flat round aria-label="Close incident" @click="close"><X :size="20"/></q-btn></header><div class="detail-body"><StatusBadge :status="selected.state"/><h2 class="incident-title">{{selected.title}}</h2><p class="muted">Opened {{date(selected.opened_at)}}<template v-if="selected.resolved_at"><br>Resolved {{date(selected.resolved_at)}}</template></p><div v-if="canAct&&selected.state==='open'" class="notice"><p>Acknowledgement stops reminders. Cronos resolves this incident after recovery is confirmed.</p><q-btn no-caps unelevated color="primary" :loading="saving" @click="acknowledge"><Check :size="17"/>Acknowledge</q-btn></div><h3>Trigger evidence</h3><div v-for="(value,key) in selected.evidence" :key="key" class="detail-line"><span>{{String(key).replace(/_/g,' ')}}</span><b>{{typeof value==='number'?Number(value.toFixed(2)):Array.isArray(value)?value.join(', '):value}}</b></div><p v-if="!Object.keys(selected.evidence).length" class="muted">Observed state triggered this rule.</p><h3>Incident timeline</h3><div class="timeline"><div v-for="event in selected.events" :key="event.id" class="timeline-event"><span class="timeline-dot"/><small>{{date(event.created_at)}} · {{event.actor_name||'Monitoring'}}</small><b>{{event.kind}}</b><p>{{event.message}}</p></div></div><form v-if="canAct" @submit.prevent="addComment" class="comment-form"><q-input v-model="comment" outlined type="textarea" rows="3" label="Add an investigation note" maxlength="2000"/><q-btn type="submit" no-caps outline :loading="saving" :disable="!comment.trim()"><MessageSquare :size="16"/>Add comment</q-btn></form><div v-if="error" class="error-box" role="alert">{{error}}</div></div></q-card></q-dialog>
</template>
